// ai-agents/harness/spikes/workflow-spike.ts — throw-away spike, not part of the harness build. On a lite VM:
//   npx tsx spikes/workflow-spike.ts ["<prompt>"]      (RESUME_SESSION_ID=<id> to resume after a kill)
import { query, type HookCallback, type Options } from "@anthropic-ai/claude-agent-sdk/core";

const logWorkflowRun: HookCallback = async (input) => {  // prints the runId, the handle for resumeFromRunId
  if (input.hook_event_name === "PostToolUse") console.log("Workflow:", JSON.stringify(input.tool_response));
  return {};
};

const options: Options = {
  model: "claude-opus-5-5",
  effort: "medium",
  cwd: "/work/fcp",
  settingSources: ["user", "project"],                  // "user" so saved workflows in ~/.claude/workflows/ load
  tools: { type: "preset", preset: "claude_code" },
  permissionMode: "dontAsk", allowedTools: ["Read", "Grep", "Glob", "Bash", "Workflow"],  // as in G3-19; try once without Workflow
  settings: JSON.stringify({ enableWorkflows: true, workflowSizeGuideline: "small" }),  // size is advice, not a cap
  pathToClaudeCodeExecutable: "/usr/local/bin/claude",  // the pinned binary the harness uses
  hooks: { PostToolUse: [{ matcher: "Workflow", hooks: [logWorkflowRun] }] },
  resume: process.env.RESUME_SESSION_ID,                // resumeFromRunId works in the same session only
  env: {
    ...process.env,                                     // env replaces process.env, so spread it
    ANTHROPIC_BASE_URL: process.env.GATEWAY_URL,        // the gateway adds the key; none in the VM
    ANTHROPIC_AUTH_TOKEN: process.env.SPIKE_RUN_TOKEN,  // a G0-13 run token for ticket SPIKE-1: the ticket rides in it
    ANTHROPIC_CUSTOM_HEADERS: "x-ai-agents-step: spike",  // G1-14's step header
    CLAUDE_CODE_WORKFLOW_MAX_CONCURRENT_AGENTS: "3",    // lite VM, 4 vCPU
  },
  // no maxTurns, no maxBudgetUsd, no taskBudget: limits never cut a run in the middle
};

const prompt = process.argv[2] ??
  "Run a small workflow: 3 parallel Haiku readers each list 5 files in frontend/src/components. Merge the lists.";

for await (const msg of query({ prompt, options })) {
  if (msg.type === "result") console.log(msg.subtype, msg.total_cost_usd, JSON.stringify(msg.modelUsage, null, 2));
}

// ai-agents/orchestrator/src/triggers/nova.ts — Nova's entry in G3-28's query registry: the 1-minute poll.
import type { Handoff } from "@rhinohealth/ai-agents-shared";
import { jira } from "../jira.js";  // G3-28's client; Nova's token from the ExternalSecret, never in a VM
import { ticketToPr } from "../workflows/ticket-to-pr.js";
import { QUERIES } from "./schedules.js";

// Runs as the Nova service account, so currentUser() is Nova.
const NOVA_JQL = "project = RH AND assignee = currentUser() AND statusCategory != Done ORDER BY updated ASC";

/** Who handed the ticket to Nova: the property /nova sets in Slack, else the latest assignee change to Nova. */
export async function requesterOf(key: string): Promise<string | undefined> {
  const fromSlack = await jira.issueProperty<string>(key, "nova.requester");  // set by /nova in Slack
  if (fromSlack) return fromSlack;
  const history = await jira.changelog(key);  // oldest first
  const toNova = history.filter((h) => h.items.some((i) => i.field === "assignee" && i.to === jira.me));
  return toNova.at(-1)?.author.accountId;
}

// ensureSchedules (G3-28) makes this the poll-jira-nova schedule: every minute, overlap SKIP. startMatches hands each
// match to startRun (G3-25): queue ai-agents-nova, ID nova:<key>, USE_EXISTING, refuses a stopped agent.
QUERIES.set("nova", {
  name: "nova", agent: "nova", jql: NOVA_JQL, every: "1 minute",
  toStart: async (issue) => {  // async, and undefined skips a match: two small changes to G3-28's toStart
    const requester = await requesterOf(issue.key);
    if (!requester) return undefined;  // no assignment to Nova found: log it, don't start a run without an owner
    const handoff: Handoff = { key: issue.key, requester };
    return [ticketToPr, handoff];  // a second poll joins the open run
  },
});

// ai-agents/orchestrator/src/commands.ts — parse "@Nova <command> [text]" from a Jira comment (ADF body).
export const COMMANDS = ["start", "answer", "retry", "stop", "approve", "change"] as const;  // approve/change: G4-14
export type Command = (typeof COMMANDS)[number];

export interface NovaCommand {
  command: Command;
  text: string;  // the rest of the comment, e.g. an answer or a plan change
  author: string;  // Jira accountId of the person who wrote it
}

interface AdfNode { type: string; text?: string; attrs?: { id?: string }; content?: AdfNode[] }
interface JiraComment { author: { accountId: string }; body: AdfNode }

const flatten = (node: AdfNode): AdfNode[] => [node, ...(node.content ?? []).flatMap(flatten)];
const isCommand = (word: string): word is Command => (COMMANDS as readonly string[]).includes(word);

export function parseCommand(comment: JiraComment, novaAccountId: string): NovaCommand | undefined {
  const author = comment.author.accountId;
  if (author === novaAccountId) return undefined;  // never react to Nova's own comments
  const nodes = flatten(comment.body);
  const at = nodes.findIndex((n) => n.type === "mention" && n.attrs?.id === novaAccountId);
  if (at === -1) return undefined;
  const rest = nodes.slice(at + 1).filter((n) => n.type === "text").map((n) => n.text ?? "").join(" ").trim();
  const [word = "", ...words] = rest.split(" ");
  const command = word.toLowerCase();
  if (isCommand(command)) return { command, text: words.join(" ").trim(), author };
  return { command: "answer", text: rest, author };  // a plain reply to Nova counts as an answer
}

// ai-agents/orchestrator/src/activities/readiness.ts — first step of every run; no VM, ticket text only.
import { readFile } from "node:fs/promises";
import { query } from "@anthropic-ai/claude-agent-sdk";
import { JiraClient } from "@rhinohealth/ai-agents-shared";
import { z } from "zod";

export const PILOT_EXCLUDED = {  // a choice by people while we learn, not a wall: Nova stops and asks
  migration: ["cloud/rhinoCloud/rhinoCore/migrations/**", "client/rhinoOnPrem/*/migrations/**"],
  auth: ["cloud/rhinoCloud/rhinoDjango/login/**", "frontend/src/app/(auth)/**", "frontend/src/app/api/auth/**"],
  grpc_contract: ["common/fcp_common/rhinoAgentRpc/**"],
  infra: [".github/workflows/**", "**/docker-compose*.yml"],
};
export const Readiness = z.object({
  verdict: z.enum(["ready", "ask", "hand_back"]), reason: z.string(),
  kind: z.enum(["fe_bug", "be_bug", "add_tests", "small_feature", "dependency_bump", "docs", "other"]),
  size: z.enum(["small", "bigger", "fuzzy"]),  // bigger → grill; fuzzy → grill + 2–3 plans
  how_to_check: z.string(),  // empty = Nova sees no way to check it
  questions: z.array(z.string()).max(5),
  out_of_scope: z.array(z.enum(["migration", "auth", "grpc_contract", "infra"])),  // the keys of PILOT_EXCLUDED
});
export type Readiness = z.infer<typeof Readiness>;

export async function checkReadiness(key: string): Promise<Readiness> {
  const ticket = await JiraClient.fromEnv().ticketText(key);  // summary, description, comments, link titles; no attachments
  for await (const msg of query({ prompt: ticket, options: {
    model: "claude-sonnet-5-5", effort: "low", tools: [], settingSources: [],  // routing table; no repo, no VM
    systemPrompt: await readFile(new URL("../../prompts/readiness.md", import.meta.url), "utf8"),
    outputFormat: { type: "json_schema", schema: z.toJSONSchema(Readiness) },
    env: { ...process.env, ANTHROPIC_AUTH_TOKEN: mintRunToken({ agent: "nova", jira: key, run: `readiness:${key}` }),
      ANTHROPIC_CUSTOM_HEADERS: "x-ai-agents-step: ticket" },  // G0-13: the ticket rides in the run token
  } })) {
    if (msg.type === "result" && msg.subtype === "success") return Readiness.parse(msg.structured_output);
  }
  throw new Error(`readiness check for ${key} returned no result`);  // the activity fails and Temporal retries it
}

// ai-agents/shared/src/schemas.ts (the Plan part) — the plan Nova writes before any code. Harness, orchestrator
// and Slack app all read it. Field names are the .nova/plan.json format, so they stay snake_case.
import { z } from "zod";

export const QACheck = z.object({
  id: z.string().regex(/^QA-\d$/),
  user_sees: z.string(),  // "With no projects, the table shows 'No projects yet'"
  reads: z.array(z.enum(["test_id", "aria_role", "visible_text", "row_count", "api_response"])).min(1),
  level: z.enum(["unit", "story", "e2e", "api", "browser_only"]),
  edge_case: z.boolean().default(false),
  proof: z.enum(["video", "screenshots_760_1440", "transcript", "test_output"]),
});
export const Step = z.object({
  what: z.string(),
  files: z.array(z.string()),
  model: z.enum(["claude-opus-5-5", "claude-sonnet-5-5", "claude-haiku-5-5"]).default("claude-opus-5-5"),
  effort: z.enum(["low", "medium", "high", "xhigh"]).default("medium"),
});
const ScreenState = z.enum(["loading", "empty", "error", "filled", "bad_data"]);
export const Plan = z.object({
  definition_of_done: z.array(z.string()).min(1).max(5),  // first, in the requester's words
  qa_plan: z.array(QACheck).min(3).max(5),
  screen_states: z.partialRecord(ScreenState, z.string()).optional(),  // UI only
  steps: z.array(Step),
  sandbox: z.enum(["lite", "full", "wide"]),  // plan small, build big
  workflow: z.string().optional(),  // why a dynamic workflow helps here, and roughly how big
  estimate_minutes: z.number().int(),  // Nova's own guess; measured, never a limit
  risk: z.enum(["low", "med", "high"]),
  risk_reason: z.string(),
}).superRefine((p, ctx) => {  // the harness sends these errors back to the planner to fix
  const ui = p.steps.some((s) => s.files.some((f) => f.startsWith("frontend/src/")));
  if (!p.qa_plan.some((c) => c.edge_case) || (ui && !p.screen_states))
    ctx.addIssue({ code: "custom", message: "the QA plan needs an edge case, and a UI change lists how to reach its screen states" });
});
export type Plan = z.infer<typeof Plan>;

// ai-agents/harness/workflows/nova-research.js — saved workflow for Nova (baked into ~/.claude/workflows/ by Packer). Plain JS.
export const meta = {
  name: 'nova-research',
  description: 'Parallel research before planning; for fuzzy tickets, 3 plans and a judge',
  phases: [{ title: 'Research' }, { title: 'Plans' }, { title: 'Judge' }],
}

const POINTERS = { type: 'object', required: ['pointers'], properties: { pointers: { type: 'array', items: {
  type: 'object', required: ['where', 'why'], properties: { where: { type: 'string' }, why: { type: 'string' } } } } } }
const QUESTIONS = [
  'Where is the code this ticket is about? Return file:line pointers, most relevant first.',
  'Find up to 5 merged fcp PRs that changed the same area (gh, read-only). Return the PR number and what it teaches.',
  'Which existing tests cover this area, and how are they run? Return file:line pointers.',
  'Search the brain with the kb skill for pages about this area; return path@sha and the key fact. If there is no kb skill, say "skipped".',
]

phase('Research')
const found = await parallel(QUESTIONS.map((q) => () =>
  agent(`${q}\n\nTicket:\n${args.ticket}`, { schema: POINTERS, model: 'haiku', effort: 'medium', phase: 'Research' })))
const notes = found.filter(Boolean).flatMap((r) => r.pointers)
if (!args.fuzzy) return { notes }

phase('Plans')
const ANGLES = ['the smallest safe change', 'risk first: what could break', 'the user first: every screen state']
const plans = await parallel(ANGLES.map((angle) => () =>
  agent(`Write a plan for this ticket, thinking ${angle}.\nTicket:\n${args.ticket}\nNotes:\n${JSON.stringify(notes)}`,
    { schema: args.planSchema, phase: 'Plans' })))

phase('Judge')
const plan = await agent(
  `Pick the plan a reviewer and a tester would trust most; graft good ideas from the others. Return the final plan.\n${JSON.stringify(plans.filter(Boolean))}`,
  { schema: args.planSchema, effort: 'medium', phase: 'Judge' })
return { notes, plan }

// ai-agents/orchestrator/src/activities/status.ts — one status comment per ticket, edited in place.
import { JiraClient } from "@rhinohealth/ai-agents-shared";
import { NOVA_STATE_FIELD } from "../jira-fields.js";  // "customfield_XXXXX": id from the Jira admin; not known yet

export type NovaState = "Checking" | "Planning" | "Awaiting approval" | "Working" | "PR open" | "Needs info" | "Stopped";
const NOTIFY = new Set<NovaState>(["Awaiting approval", "Needs info", "PR open"]);  // only the states that need a person

export interface Status {
  key: string;
  state: NovaState;
  doing: string;  // one plain line: "Writing the QA checks as tests"
  links: Record<string, string>;  // plan, slack thread, trace
  commentId?: string;  // kept in workflow state
}

function adf(s: Status) {
  const text = `Nova: ${s.state}. ${s.doing}  ` + Object.entries(s.links).map(([k, v]) => `${k}: ${v}`).join(" · ");
  return { type: "doc", version: 1, content: [{ type: "paragraph", content: [{ type: "text", text }] }] };
}

export async function setStatus(s: Status): Promise<string> {
  const jira = JiraClient.fromEnv();
  await jira.updateIssue(s.key, { [NOVA_STATE_FIELD]: { value: s.state } });
  if (s.commentId === undefined) return jira.addComment(s.key, adf(s));  // returns the new comment id
  await jira.editComment(s.key, s.commentId, adf(s), { notifyUsers: NOTIFY.has(s.state) });
  return s.commentId;
}

// ai-agents/orchestrator/src/workflows/ticket-to-pr.ts — the grill block inside G3's ticketToPr (G3 owns the rest).
// Workflow code: deterministic, no Node APIs, no fetch. Handoff, RunState: @rhinohealth/ai-agents-shared (G3-24); setState, flagToRequester: small helpers here.
import { proxyActivities } from "@temporalio/workflow";
import type * as activities from "../activities/index.js";
import type { Readiness } from "../activities/readiness.js";
import { waitForPerson } from "../waiting.js";  // G3: remind after 1 day, park after 2
import { LONG } from "../policies.js";  // G3-29: a 7-day safety net and 2-minute heartbeats, never a work limit

const { checkReadiness } = proxyActivities<typeof activities>({ startToCloseTimeout: "5 minutes" });
const { writeGrillQuestions } = proxyActivities<typeof activities>(LONG);  // an Opus session: never cut off
const { handBack, postQuestions, recordAnswers } = proxyActivities<typeof activities>({ startToCloseTimeout: "2 minutes" });

async function readinessAndGrill(h: Handoff, run: RunState): Promise<Readiness | undefined> {
  let r = await checkReadiness(h.key);
  if (r.verdict === "hand_back") {
    await handBack(h.key, h.requester, r.reason);
    return undefined;
  }
  let rounds = 0;
  while (r.verdict === "ask" || (r.size !== "small" && rounds === 0)) {
    const questions = r.questions.length ? r.questions : await writeGrillQuestions(h.key);  // Opus 5.5 medium, no VM
    if (!questions.length) break;
    await setState(run, "Needs info", `${questions.length} questions for the requester`);
    run.answer = undefined;  // before posting, so a quick answer is not lost; the answerQuestion signal (G3) sets it
    await postQuestions(h.key, h.requester, questions);
    if (!(await waitForPerson(run, "question", () => run.answer !== undefined, h))) return undefined;  // parked or stopped
    await recordAnswers(h.key, questions, run.answer!);
    r = await checkReadiness(h.key);
    rounds += 1;
    if (rounds === 2 && r.verdict === "ask") {
      await flagToRequester(run, "The same questions are still open. Please edit the ticket or reply.");
      break;
    }
  }
  return r;
}

// ai-agents/harness/src/qa.ts (part 1) — the QA agent co-signs the QA plan. It sees the ticket and the checks, nothing else.
import { readFile } from "node:fs/promises";
import { query } from "@anthropic-ai/claude-agent-sdk/core";
import { z } from "zod";

const PROBLEMS = ["not_observable", "no_edge_case", "missing_screen_state", "reads_implementation", "wrong_proof",
  "not_the_ticket"] as const;
export const Cosign = z.object({
  sign: z.boolean(),
  changes: z.array(z.object({
    check: z.string(),  // "QA-2", or "new" for a missing check
    problem: z.enum(PROBLEMS),
    suggestion: z.string(),
  })),
});
export type Cosign = z.infer<typeof Cosign>;

export async function cosign(ticketText: string, qaPlanJson: string): Promise<Cosign> {
  const prompt = `Ticket:\n${ticketText}\n\nProposed QA plan:\n${qaPlanJson}\n\nWould these checks fail on a broken build?`;
  for await (const msg of query({ prompt, options: {
    model: "claude-sonnet-5-5", effort: "medium", tools: [], settingSources: [],  // its own session, not a Nova subagent
    systemPrompt: await readFile(new URL("../prompts/qa-cosign.md", import.meta.url), "utf8"),  // goals + 4 weak-plan examples
    outputFormat: { type: "json_schema", schema: z.toJSONSchema(Cosign) },
  } })) {
    if (msg.type === "result" && msg.subtype === "success") return Cosign.parse(msg.structured_output);
  }
  throw new Error("the QA agent returned no co-sign result");
}

// ai-agents/harness/src/checks.ts — suggestions, and the record behind the PR's checks table (.nova/checks.json).
import { z } from "zod";

export const CheckRun = z.object({
  name: z.string(),  // "vitest related", "e2e/pr/projects-table-empty-state.spec.ts"
  command: z.string(),
  result: z.enum(["pass", "fail", "fails_on_main_too", "not_run"]),
  why: z.string(),  // one line for the reviewer
  proof: z.string().nullish(),  // S3 key of the output, video or trace
  qa_check: z.string().nullish(),  // "QA-2" when it proves a QA plan check
});
export const ChecksRecord = z.object({
  kind: z.string(),  // from readiness: fe_bug, be_bug, ...
  services_started: z.array(z.string()),  // [] for a lint-only change
  ran: z.array(CheckRun),
  skipped: z.array(z.tuple([z.string(), z.string()])),  // [check, reason]
});

/** A starting point from the checking guide. Nova decides; this never blocks or forces a check. */
export function suggestStart(changed: string[]): { checks: string[]; services: string[] } {
  const fe = changed.filter((p) => p.startsWith("frontend/src/"));
  const be = changed.filter((p) => p.startsWith("cloud/") || p.startsWith("client/"));
  const checks: string[] = [];
  const services: string[] = [];
  if (fe.length) {
    checks.push("npm run lint", "npm run check-types", "npx vitest --run --changed origin/main");
    if (fe.some((p) => p.startsWith("frontend/src/app/"))) {
      checks.push("the Playwright spec for this flow (frontend/e2e/pr/)");
      services.push("postgres-service", "web-service", "redis");  // cloud/rhinoCloud/docker-compose.yml names
    }
  }
  if (be.length) checks.push("pre-commit run --files <changed>", "./scripts/local_run_backend_unit_tests.sh cloud <module path>");
  return { checks, services };
}

// ai-agents/harness/src/hooks/locked-checks.ts — a wall: Nova may add tests, not change the ones it is judged by.
import { createHash } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { relative, resolve } from "node:path";
import type { HookCallback } from "@anthropic-ai/claude-agent-sdk/core";

const REPO = "/work/fcp";
const LOCK = "/work/.nova/locked.json";  // outside the checkout; path per G3's harness layout

const digest = (rel: string) => createHash("sha256").update(readFileSync(resolve(REPO, rel))).digest("hex");
const locked = (): Record<string, string> => (existsSync(LOCK) ? JSON.parse(readFileSync(LOCK, "utf8")) : {});

/** Called by the harness once every QA test was shown failing on the unchanged code. */
export function lock(testFiles: string[]): void {
  writeFileSync(LOCK, JSON.stringify(Object.fromEntries(testFiles.map((rel) => [rel, digest(rel)]))));
}

export const denyLockedEdits: HookCallback = async (input) => {  // PreToolUse, matcher "Edit|Write"
  if (input.hook_event_name !== "PreToolUse") return {};
  const path = (input.tool_input as { file_path?: string }).file_path;
  if (!path || !Object.hasOwn(locked(), relative(REPO, resolve(path)))) return {};
  return { hookSpecificOutput: {
    hookEventName: "PreToolUse",
    permissionDecision: "deny",
    permissionDecisionReason: "This test is a locked QA check for this ticket. Add a new test instead, " +
      "or ask the requester to change the QA plan.",
  } };
};

/** For the Stop hook: catches edits made through Bash too. */
export function changedLockedFiles(): string[] {
  const changed = (rel: string, d: string) => !existsSync(resolve(REPO, rel)) || digest(rel) !== d;
  return Object.entries(locked()).filter(([rel, d]) => changed(rel, d)).map(([rel]) => rel);
}

// ai-agents/harness/src/judges/scope.ts — sees ONLY the ticket and the diff. Never the plan, the transcript or Nova's notes.
import { query } from "@anthropic-ai/claude-agent-sdk/core";
import { z } from "zod";
import { testChanges } from "./test-changes.js";  // mechanical: removed assertions, .skip/.only, @skip, longer timeouts

const SCOPE_PROMPT = `You review a pull request for scope, as a careful reviewer from another team would.
You get the ticket and the diff, nothing else. Decide whether every change serves the ticket.

Veto when you see:
- a change the ticket does not need: refactors, renames, reformatting or "while I was here" fixes in other code;
- a test made weaker: removed or loosened assertions, skipped tests, longer timeouts, fewer cases, lower thresholds.

Small supporting changes the ticket clearly needs are fine (a new test ID, a helper the fix uses, a type).
When you are unsure, say so in the note and pass. Cite the file and lines for every item.`;

const Item = z.object({ path: z.string(), lines: z.string(), why: z.string() });
export const ScopeVerdict = z.object({
  verdict: z.enum(["pass", "veto"]), unrelated: z.array(Item), weakened_tests: z.array(Item), note: z.string(),
});
export type ScopeVerdict = z.infer<typeof ScopeVerdict>;

export async function scopeJudge(ticket: string, diff: string): Promise<ScopeVerdict> {
  const prompt = `Ticket:\n${ticket}\n\nDiff:\n${diff}\n\nTest changes:\n${testChanges(diff)}`;
  for await (const msg of query({ prompt, options: {
    model: "claude-sonnet-5-5", effort: "medium", tools: [], settingSources: [],  // a rubric judge in its own session
    systemPrompt: SCOPE_PROMPT,
    outputFormat: { type: "json_schema", schema: z.toJSONSchema(ScopeVerdict) },
  } })) {
    if (msg.type === "result" && msg.subtype === "success") return ScopeVerdict.parse(msg.structured_output);
  }
  throw new Error("the scope judge returned no verdict");
}

// ai-agents/harness/src/review.ts — the self-review reviewer. Its own query() session with a fixed prompt: it sees
// the ticket, the approved plan and the diff, never Nova's transcript or notes.
import { execFile } from "node:child_process";
import { writeFile } from "node:fs/promises";
import { promisify } from "node:util";
import { query } from "@anthropic-ai/claude-agent-sdk/core";
import { z } from "zod";

const LENSES = "/opt/ai-agents/byte-playbooks";  // Byte's lens files, baked into the image

export const Finding = z.object({
  path: z.string(), line: z.number().int(), rule: z.string(), severity: z.enum(["important", "nit"]), body: z.string(),
});
export type Finding = z.infer<typeof Finding>;
const Findings = z.object({ findings: z.array(Finding) });

const PROMPT = `You review a change you did not write. Read the ticket, the approved plan and the diff in /run/nova/review/diff.patch.
Use the lenses in ${LENSES}. Report what matters: bugs, security problems, a requirement or plan item that is missing,
and changes the plan did not ask for. Mark each finding important or nit, with path and line.
Don't list every possible improvement. No findings is a fine answer for a clean diff.`;

export async function reviewOnce(ticket: string, planMd: string): Promise<Finding[]> {
  const { stdout } = await promisify(execFile)("git", ["diff", "origin/main...HEAD"], { cwd: "/work/fcp", maxBuffer: 64 << 20 });
  await writeFile("/run/nova/review/diff.patch", stdout);  // the harness runs git; the reviewer only reads
  const prompt = `Ticket:\n${ticket}\n\nApproved plan:\n${planMd}`;
  for await (const msg of query({ prompt, options: {
    model: "claude-opus-5-5", effort: "medium",  // logic and security, per the routing table
    cwd: "/work/fcp", settingSources: ["project"],  // repo conventions (frontend/AGENTS.md) still apply
    systemPrompt: PROMPT,
    allowedTools: ["Read", "Grep", "Glob"],  // no Bash: git diff --no-index or --output= could read or write outside the repo
    disallowedTools: ["Bash", "Edit", "Write", "NotebookEdit", "WebFetch", "WebSearch"],
    permissionMode: "dontAsk",  // anything not allowed above is refused
    additionalDirectories: [LENSES, "/run/nova/review"],
    outputFormat: { type: "json_schema", schema: z.toJSONSchema(Findings) },
  } })) {
