# ai-agents/evals/ticket_bench/score.py — pass@1, pass^3, cost and minutes, split by kind. Python, next to Harbor.
import json
import sys
from collections import defaultdict
from math import comb
from statistics import mean, median


def pass_hat_k(successes: int, tries: int, k: int) -> float:
    """Chance that k tries picked from this task's runs all pass (tau-bench's pass^k)."""
    return comb(successes, k) / comb(tries, k) if tries >= k else float("nan")


def score(rows: list[dict]) -> dict:
    by_task = defaultdict(list)
    for r in rows:  # one row per trial: task, kind, reward, cost_usd, minutes
        by_task[(r["kind"], r["task"])].append(r)
    by_kind = defaultdict(list)
    for (kind, _), trials in by_task.items():
        wins = sum(t["reward"] == 1 for t in trials)
        by_kind[kind].append({"p1": wins / len(trials), "p3": pass_hat_k(wins, len(trials), 3),
                              "cost": mean(t["cost_usd"] for t in trials), "min": median(t["minutes"] for t in trials)})
    return {kind: {"tasks": len(v),
                   "pass@1": round(mean(x["p1"] for x in v), 3),
                   "pass^3": round(mean(x["p3"] for x in v), 3),
                   "cost_per_task_usd": round(mean(x["cost"] for x in v), 2),  # measured, never a limit
                   "minutes_per_task": round(median(x["min"] for x in v), 1)}
            for kind, v in sorted(by_kind.items())}


if __name__ == "__main__":
    print(json.dumps(score([json.loads(line) for line in open(sys.argv[1])]), indent=2))

// ai-agents/orchestrator/src/activities/ready-gate.ts — draft → ready only when clean.
import type { GateEvidence } from "@rhinohealth/ai-agents-shared";  // qa_results, scope_judge, pr_judge, findings, reviewer_team
import { gh } from "../broker-client.js";  // every GitHub call goes through the broker, scoped to one repo

const DONE = new Set(["fixed", "answered", "with_a_person"]);

export interface GateResult {
  ready: boolean;
  blockers: string[];
}

export async function readyGate(pr: number, ev: GateEvidence): Promise<GateResult> {
  const checks = await gh<{ name: string; bucket: string }[]>(["pr", "checks", String(pr), "--required", "--json", "name,bucket"]);
  const blockers = checks.filter((c) => c.bucket !== "pass" && c.bucket !== "skipping")
    .map((c) => `CI: ${c.name} is ${c.bucket}`);
  blockers.push(...ev.qa_results.filter((q) => !q.passed).map((q) => `QA check ${q.id} failed`));
  if (ev.scope_judge.verdict === "veto" && !ev.scope_judge.explained) blockers.push("scope judge veto not resolved");
  if (!ev.pr_judge.ready) blockers.push("PR judge: the description has open items");
  const open = ev.findings.filter((f) => f.severity === "important" && !DONE.has(f.state));
  blockers.push(...open.map((f) => `open finding ${f.path}:${f.line}`));
  if (blockers.length) return { ready: false, blockers };  // stays a draft; nobody is pinged
  await gh(["pr", "ready", String(pr)]);
  await gh(["pr", "edit", String(pr), "--add-reviewer", ev.reviewer_team]);  // e.g. RhinoHealth/frontend-guild
  return { ready: true, blockers: [] };
}
